from itertools import permutations

# Generate all possible permutations of 0..6
perms = list(permutations(range(7)))

# Initialize an empty grid
grid = [[0]*7 for _ in range(7)]

# Iterate over all permutations
for p in perms:
    # Check if the permutation satisfies the idempotent diagonal condition
    if all(p[i] == i for i in range(7)):
        # Check if the permutation satisfies the QG3 condition
        if all(p[p[i]] == i for i in range(7)):
            # If both conditions are satisfied, fill in the grid
            for i in range(7):
                for j in range(7):
                    grid[i][j] = p[(i+j)%7]
            # Print the grid as a flat list
            print([grid[i][j] for i in range(7) for j in range(7)])
            break
else:
    print("UNSATISFIABLE")
